import React, { useState, useEffect } from 'react';
import api from '../../services/api';
import ImageUploadButton from '../../components/ImageUploadButton';


// Modal para asignar grupos de opciones a un producto Y elegir, opción por opción,
// cuáles de ellas aplican a ESE producto puntual (ej: un jugo no ofrece "sirope de vainilla").
const AssignModifiersModal = ({ product, allModifiers, onClose, onChanged }) => {
  const [busyId, setBusyId] = useState(null);
  const [settings, setSettings] = useState({}); // { [modifier_id]: { is_required, disabled_option_ids } }
  const [loadingSettings, setLoadingSettings] = useState(true);

  useEffect(() => {
    fetchSettings();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [product?.id]);

  const fetchSettings = async () => {
    if (!product) return;
    setLoadingSettings(true);
    try {
      const res = await api.get(`/products/${product.id}/modifier-settings`);
      const map = {};
      (res.data.data || []).forEach(row => {
        map[row.modifier_id] = {
          is_required: !!row.is_required,
          disabled_option_ids: row.disabled_option_ids || [],
        };
      });
      setSettings(map);
    } catch (err) {
      console.error('Error cargando configuración de opciones:', err);
    } finally {
      setLoadingSettings(false);
    }
  };

  if (!product) return null;

  const assignedIds = new Set(Object.keys(settings).map(Number));

  const toggleGroup = async (modifier) => {
    setBusyId(modifier.id);
    try {
      if (assignedIds.has(modifier.id)) {
        await api.delete(`/products/${product.id}/modifiers/${modifier.id}`);
      } else {
        await api.post('/products/assign-modifier', {
          product_id: product.id,
          modifier_id: modifier.id,
          is_required: false,
          disabled_option_ids: [],
        });
      }
      await fetchSettings();
      await onChanged();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al actualizar las opciones');
    } finally {
      setBusyId(null);
    }
  };

  const toggleOption = async (modifier, optionId) => {
    const current = settings[modifier.id] || { is_required: false, disabled_option_ids: [] };
    const disabled = new Set(current.disabled_option_ids || []);
    if (disabled.has(optionId)) {
      disabled.delete(optionId);
    } else {
      disabled.add(optionId);
    }
    const newDisabled = Array.from(disabled);

    // Actualización optimista
    setSettings(prev => ({ ...prev, [modifier.id]: { ...current, disabled_option_ids: newDisabled } }));

    try {
      await api.put(`/products/${product.id}/modifiers/${modifier.id}`, {
        disabled_option_ids: newDisabled,
      });
      await onChanged();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al guardar la opción');
      fetchSettings();
    }
  };

  const toggleRequired = async (modifier) => {
    const current = settings[modifier.id] || { is_required: false, disabled_option_ids: [] };
    const newRequired = !current.is_required;
    setSettings(prev => ({ ...prev, [modifier.id]: { ...current, is_required: newRequired } }));
    try {
      await api.put(`/products/${product.id}/modifiers/${modifier.id}`, { is_required: newRequired });
    } catch (err) {
      alert('Error al actualizar');
      fetchSettings();
    }
  };

  return (
    <div style={{
      position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
      background: 'rgba(0,0,0,0.8)', zIndex: 600,
      display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20,
    }} onClick={onClose}>
      <div className="card animate-fade-in" style={{ maxWidth: 520, width: '100%', maxHeight: '85vh', overflowY: 'auto' }} onClick={e => e.stopPropagation()}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <h3 style={{ color: '#e2e8f0' }}>⚙️ Opciones de: {product.name}</h3>
          <button onClick={onClose} style={{ background: '#334155', color: '#e2e8f0', border: 'none', borderRadius: '50%', width: 32, height: 32, cursor: 'pointer' }}>✕</button>
        </div>

        {allModifiers.length === 0 && (
          <p style={{ color: '#64748b', fontSize: 13, marginBottom: 12 }}>
            Todavía no creaste ningún grupo de opciones. Crea uno abajo en "Opciones / Modificadores" y luego actívalo aquí.
          </p>
        )}

        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {allModifiers.map(mod => {
            const active = assignedIds.has(mod.id);
            const cfg = settings[mod.id] || { is_required: false, disabled_option_ids: [] };
            return (
              <div key={mod.id} style={{
                borderRadius: 10, border: '1px solid',
                borderColor: active ? '#38bdf8' : '#334155',
                background: active ? 'rgba(56, 189, 248, 0.06)' : '#0f172a',
                padding: '12px 14px',
              }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <p style={{ color: '#e2e8f0', fontWeight: 600, fontSize: 14 }}>{mod.name}</p>
                    <p style={{ color: '#64748b', fontSize: 12 }}>
                      {mod.options?.length || 0} opciones · {mod.description || 'Sin descripción'}
                    </p>
                  </div>
                  <button
                    onClick={() => toggleGroup(mod)}
                    disabled={busyId === mod.id}
                    className={active ? 'btn btn-danger' : 'btn btn-primary'}
                    style={{ padding: '6px 14px', fontSize: 12, whiteSpace: 'nowrap' }}
                  >
                    {busyId === mod.id ? '...' : active ? 'Quitar' : 'Activar'}
                  </button>
                </div>

                {active && !loadingSettings && (
                  <div style={{ marginTop: 12, paddingTop: 12, borderTop: '1px solid #334155' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 }}>
                      <input
                        type="checkbox"
                        id={`req-${mod.id}`}
                        checked={cfg.is_required}
                        onChange={() => toggleRequired(mod)}
                        style={{ width: 16, height: 16 }}
                      />
                      <label htmlFor={`req-${mod.id}`} style={{ color: '#94a3b8', fontSize: 12 }}>
                        Obligatorio en este producto
                      </label>
                    </div>

                    <p style={{ color: '#64748b', fontSize: 11, marginBottom: 8, textTransform: 'uppercase', letterSpacing: 0.5 }}>
                      Elige qué opciones aplican a este producto
                    </p>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                      {mod.options?.map(opt => {
                        const included = !(cfg.disabled_option_ids || []).includes(opt.id);
                        return (
                          <label key={opt.id} style={{
                            display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                            padding: '6px 10px', borderRadius: 6, cursor: 'pointer',
                            background: included ? 'rgba(16,185,129,0.06)' : 'transparent',
                          }}>
                            <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                              <input
                                type="checkbox"
                                checked={included}
                                onChange={() => toggleOption(mod, opt.id)}
                                style={{ width: 15, height: 15 }}
                              />
                              <span style={{ color: included ? '#e2e8f0' : '#64748b', fontSize: 13 }}>{opt.name}</span>
                            </span>
                            <span style={{ color: parseFloat(opt.price_adjustment) > 0 ? '#fbbf24' : '#64748b', fontSize: 12 }}>
                              {parseFloat(opt.price_adjustment) > 0 ? `+$${parseFloat(opt.price_adjustment).toFixed(2)}` : 'Incluido'}
                            </span>
                          </label>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

// Modal para editar un grupo de opciones: nombre, descripción, mín/máx,
// y agregar/editar/quitar opciones individuales (ej: quitar "Con leche de soya").
const EditModifierModal = ({ modifier, onClose, onSaved }) => {
  const [form, setForm] = useState({
    name: modifier.name || '',
    description: modifier.description || '',
    min_selections: modifier.min_selections ?? 0,
    max_selections: modifier.max_selections ?? 1,
  });
  const [options, setOptions] = useState((modifier.options || []).map(o => ({ ...o })));
  const [newOption, setNewOption] = useState({ name: '', price_adjustment: '0' });
  const [saving, setSaving] = useState(false);

  const saveGroup = async () => {
    setSaving(true);
    try {
      await api.put(`/modifiers/${modifier.id}`, {
        name: form.name,
        description: form.description,
        min_selections: parseInt(form.min_selections) || 0,
        max_selections: parseInt(form.max_selections) || 1,
      });
      await onSaved();
      onClose();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al guardar');
    } finally {
      setSaving(false);
    }
  };

  const updateOptionField = (id, field, value) => {
    setOptions(prev => prev.map(o => o.id === id ? { ...o, [field]: value } : o));
  };

  const saveOption = async (option) => {
    try {
      await api.put(`/modifier-options/${option.id}`, {
        name: option.name,
        price_adjustment: parseFloat(option.price_adjustment) || 0,
      });
      await onSaved();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al guardar la opción');
    }
  };

  const deleteOption = async (option) => {
    if (!window.confirm(`¿Quitar la opción "${option.name}"?`)) return;
    try {
      await api.delete(`/modifier-options/${option.id}`);
      setOptions(prev => prev.filter(o => o.id !== option.id));
      await onSaved();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al eliminar la opción');
    }
  };

  const addOption = async () => {
    if (!newOption.name.trim()) return;
    try {
      const res = await api.post(`/modifiers/${modifier.id}/options`, {
        name: newOption.name.trim(),
        price_adjustment: parseFloat(newOption.price_adjustment) || 0,
      });
      setOptions(prev => [...prev, res.data.data]);
      setNewOption({ name: '', price_adjustment: '0' });
      await onSaved();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al agregar la opción');
    }
  };

  return (
    <div style={{
      position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
      background: 'rgba(0,0,0,0.8)', zIndex: 600,
      display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20,
    }} onClick={onClose}>
      <div className="card animate-fade-in" style={{ maxWidth: 520, width: '100%', maxHeight: '85vh', overflowY: 'auto' }} onClick={e => e.stopPropagation()}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <h3 style={{ color: '#e2e8f0' }}>✏️ Editar grupo de opciones</h3>
          <button onClick={onClose} style={{ background: '#334155', color: '#e2e8f0', border: 'none', borderRadius: '50%', width: 32, height: 32, cursor: 'pointer' }}>✕</button>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 10, marginBottom: 16 }}>
          <input type="text" placeholder="Nombre" className="input" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} />
          <input type="text" placeholder="Descripción" className="input" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} />
          <div>
            <label style={{ color: '#94a3b8', fontSize: 11, display: 'block', marginBottom: 4 }}>Mín selecciones</label>
            <input type="number" min="0" className="input" value={form.min_selections} onChange={e => setForm({ ...form, min_selections: e.target.value })} />
          </div>
          <div>
            <label style={{ color: '#94a3b8', fontSize: 11, display: 'block', marginBottom: 4 }}>Máx selecciones</label>
            <input type="number" min="1" className="input" value={form.max_selections} onChange={e => setForm({ ...form, max_selections: e.target.value })} />
          </div>
        </div>
        <button onClick={saveGroup} disabled={saving} className="btn btn-primary" style={{ width: '100%', marginBottom: 20 }}>
          {saving ? 'Guardando...' : '💾 Guardar datos del grupo'}
        </button>

        <h4 style={{ color: '#94a3b8', fontSize: 12, textTransform: 'uppercase', letterSpacing: 1, marginBottom: 10 }}>
          Opciones de este grupo
        </h4>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 16 }}>
          {options.map(opt => (
            <div key={opt.id} style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <input
                type="text"
                className="input"
                style={{ flex: 1 }}
                value={opt.name}
                onChange={e => updateOptionField(opt.id, 'name', e.target.value)}
              />
              <input
                type="number"
                step="0.01"
                className="input"
                style={{ width: 110 }}
                value={opt.price_adjustment}
                onChange={e => updateOptionField(opt.id, 'price_adjustment', e.target.value)}
              />
              <button onClick={() => saveOption(opt)} style={{ background: 'rgba(16,185,129,0.1)', color: '#10b981', border: 'none', borderRadius: 8, width: 36, height: 36, cursor: 'pointer' }} title="Guardar">💾</button>
              <button onClick={() => deleteOption(opt)} style={{ background: 'rgba(239,68,68,0.1)', color: '#ef4444', border: 'none', borderRadius: 8, width: 36, height: 36, cursor: 'pointer' }} title="Quitar opción">🗑️</button>
            </div>
          ))}
          {options.length === 0 && (
            <p style={{ color: '#64748b', fontSize: 13 }}>Este grupo no tiene opciones. Agrega una abajo.</p>
          )}
        </div>

        <div style={{ display: 'flex', gap: 8 }}>
          <input
            type="text"
            placeholder="Nueva opción (ej: Con canela)"
            className="input"
            style={{ flex: 1 }}
            value={newOption.name}
            onChange={e => setNewOption({ ...newOption, name: e.target.value })}
          />
          <input
            type="number"
            step="0.01"
            placeholder="+/- precio"
            className="input"
            style={{ width: 110 }}
            value={newOption.price_adjustment}
            onChange={e => setNewOption({ ...newOption, price_adjustment: e.target.value })}
          />
          <button onClick={addOption} className="btn btn-success" style={{ padding: '0 16px' }}>+ Agregar</button>
        </div>
      </div>
    </div>
  );
};

const MenuPage = () => {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [modifiers, setModifiers] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategoryTab, setActiveCategoryTab] = useState('all');

  const [form, setForm] = useState({
    name: '', description: '', history: '', ingredients: '',
    price: '', cost: '', category_id: '', preparation_time_min: 15,
    image_url: '', model_3d_url: '', is_available: true,
    is_combo: false,
  });
  const [comboItems, setComboItems] = useState({}); // { [product_id]: quantity }

  // Sección de opciones / modificadores
  const [showModifierForm, setShowModifierForm] = useState(false);
  const [modifierForm, setModifierForm] = useState(emptyModifierForm());
  const [assignModalProduct, setAssignModalProduct] = useState(null);
  const [editModifierTarget, setEditModifierTarget] = useState(null);

  // Categorías: crear/editar
  const [showCategoryForm, setShowCategoryForm] = useState(false);
  const [editingCategory, setEditingCategory] = useState(null);
  const [categoryForm, setCategoryForm] = useState({ name: '', description: '', icon: '🍽️' });

  // Drag & drop
  const [draggedProductId, setDraggedProductId] = useState(null);
  const [draggedCategoryId, setDraggedCategoryId] = useState(null);

  function emptyModifierForm() {
    return {
      name: '', description: '', min_selections: 0, max_selections: 1,
      options: [{ name: '', price_adjustment: '0' }],
    };
  }

  useEffect(() => {
    fetchData();
    fetchModifiers();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    setError('');
    try {
      const res = await api.get('/menu/SUC-001');
      if (res.data.status) {
        const cats = res.data.data.categories || [];
        setCategories(cats);
        const all = [];
        cats.forEach(c => {
          (c.products || []).forEach(p => {
            all.push({ ...p, categoryName: c.name });
          });
        });
        setProducts(all);
      } else {
        setError(res.data.message || 'Error del servidor');
      }
    } catch (err) {
      console.error(err);
      const backendMsg = err.response?.data?.message;
      const statusCode = err.response?.status;
      if (backendMsg) {
        setError(`Error del servidor (${statusCode}): ${backendMsg}`);
      } else if (err.request && !err.response) {
        setError('No se pudo conectar con Laravel. Verifica que el backend esté corriendo (php artisan serve).');
      } else {
        setError(`Error inesperado: ${err.message}`);
      }
    } finally {
      setLoading(false);
    }
  };

  const fetchModifiers = async () => {
    try {
      const res = await api.get('/modifiers');
      if (res.data.status) setModifiers(res.data.data || []);
    } catch (err) {
      console.error('Error cargando opciones:', err);
    }
  };

  // ===== Productos =====

  const resetForm = () => {
    setForm({ name: '', description: '', history: '', ingredients: '', price: '', cost: '', category_id: '', preparation_time_min: 15, image_url: '', model_3d_url: '', is_available: true, is_combo: false });
    setComboItems({});
    setEditingProduct(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const combo_items = Object.entries(comboItems)
        .filter(([, qty]) => parseInt(qty) > 0)
        .map(([product_id, quantity]) => ({ product_id: parseInt(product_id), quantity: parseInt(quantity) }));

      if (form.is_combo && combo_items.length === 0) {
        alert('Selecciona al menos un producto para armar el combo');
        return;
      }

      const data = { ...form, branch_id: 1, combo_items: form.is_combo ? combo_items : [] };
      if (editingProduct) {
        await api.put(`/products/${editingProduct.id}`, data);
      } else {
        await api.post('/products', data);
      }
      setShowForm(false);
      resetForm();
      fetchData();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al guardar');
    }
  };

  const toggleAvailability = async (id, current) => {
    try {
      await api.put(`/products/${id}`, { is_available: !current });
      fetchData();
    } catch (err) {
      alert('Error al actualizar');
    }
  };

  const deleteProduct = async (id) => {
    if (!window.confirm('¿Eliminar este producto?')) return;
    try {
      await api.delete(`/products/${id}`);
      fetchData();
    } catch (err) {
      alert('Error al eliminar');
    }
  };

  const duplicateProduct = async (id) => {
    try {
      await api.post(`/products/${id}/duplicate`);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al duplicar el producto');
    }
  };

  const startEdit = (product) => {
    setEditingProduct(product);
    setForm({
      name: product.name || '',
      description: product.description || '',
      history: product.history || '',
      ingredients: product.ingredients || '',
      price: product.price || '',
      cost: product.cost || '',
      category_id: product.category_id || '',
      preparation_time_min: product.preparation_time_min || 15,
      image_url: product.image_url || '',
      model_3d_url: product.model_3d_url || '',
      is_available: product.is_available !== false,
      is_combo: !!product.is_combo,
    });
    const map = {};
    (product.combo_items || []).forEach(ci => { map[ci.product_id] = ci.quantity || 1; });
    setComboItems(map);
    setShowForm(true);
  };

  // Reordenar productos con drag & drop (solo tiene sentido dentro de una categoría puntual)
  const handleProductDrop = async (targetProduct) => {
    if (draggedProductId === null || draggedProductId === targetProduct.id) return;
    if (activeCategoryTab === 'all') return; // evitar reordenar mezclando categorías

    const catProducts = products.filter(p => p.category_id === targetProduct.category_id);
    const otherProducts = products.filter(p => p.category_id !== targetProduct.category_id);

    const fromIndex = catProducts.findIndex(p => p.id === draggedProductId);
    const toIndex = catProducts.findIndex(p => p.id === targetProduct.id);
    if (fromIndex === -1 || toIndex === -1) return;

    const reordered = [...catProducts];
    const [moved] = reordered.splice(fromIndex, 1);
    reordered.splice(toIndex, 0, moved);

    setProducts([...otherProducts, ...reordered]);
    setDraggedProductId(null);

    try {
      await api.post('/products/reorder', {
        items: reordered.map((p, idx) => ({ id: p.id, sort_order: idx })),
      });
    } catch (err) {
      alert('Error al guardar el nuevo orden');
      fetchData();
    }
  };

  // ===== Categorías =====

  const resetCategoryForm = () => {
    setCategoryForm({ name: '', description: '', icon: '🍽️' });
    setEditingCategory(null);
  };

  const submitCategoryForm = async (e) => {
    e.preventDefault();
    try {
      if (editingCategory) {
        await api.put(`/categories/${editingCategory.id}`, categoryForm);
      } else {
        await api.post('/categories', { ...categoryForm, branch_id: 1 });
      }
      setShowCategoryForm(false);
      resetCategoryForm();
      fetchData();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al guardar la categoría');
    }
  };

  const startEditCategory = (cat) => {
    setEditingCategory(cat);
    setCategoryForm({ name: cat.name || '', description: cat.description || '', icon: cat.icon || '🍽️' });
    setShowCategoryForm(true);
  };

  const deleteCategory = async (cat) => {
    if (!window.confirm(`¿Eliminar la categoría "${cat.name}"?`)) return;
    try {
      await api.delete(`/categories/${cat.id}`);
      if (activeCategoryTab === cat.id) setActiveCategoryTab('all');
      fetchData();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al eliminar la categoría');
    }
  };

  const handleCategoryDrop = async (targetCat) => {
    if (draggedCategoryId === null || draggedCategoryId === targetCat.id) return;

    const fromIndex = categories.findIndex(c => c.id === draggedCategoryId);
    const toIndex = categories.findIndex(c => c.id === targetCat.id);
    if (fromIndex === -1 || toIndex === -1) return;

    const reordered = [...categories];
    const [moved] = reordered.splice(fromIndex, 1);
    reordered.splice(toIndex, 0, moved);

    setCategories(reordered);
    setDraggedCategoryId(null);

    try {
      await api.post('/categories/reorder', {
        items: reordered.map((c, idx) => ({ id: c.id, sort_order: idx })),
      });
    } catch (err) {
      alert('Error al guardar el nuevo orden');
      fetchData();
    }
  };

  // ===== Opciones / Modificadores =====

  const updateModifierOption = (index, field, value) => {
    setModifierForm(f => {
      const options = [...f.options];
      options[index] = { ...options[index], [field]: value };
      return { ...f, options };
    });
  };

  const addModifierOptionRow = () => {
    setModifierForm(f => ({ ...f, options: [...f.options, { name: '', price_adjustment: '0' }] }));
  };

  const removeModifierOptionRow = (index) => {
    setModifierForm(f => ({ ...f, options: f.options.filter((_, i) => i !== index) }));
  };

  const submitModifierForm = async (e) => {
    e.preventDefault();
    const cleanOptions = modifierForm.options
      .filter(o => o.name.trim() !== '')
      .map(o => ({ name: o.name.trim(), price_adjustment: parseFloat(o.price_adjustment) || 0 }));

    if (cleanOptions.length === 0) {
      alert('Agrega al menos una opción (ej: "Con papas", "Sin papas")');
      return;
    }

    try {
      await api.post('/modifiers', {
        branch_id: 1,
        name: modifierForm.name,
        description: modifierForm.description || undefined,
        min_selections: parseInt(modifierForm.min_selections) || 0,
        max_selections: parseInt(modifierForm.max_selections) || 1,
        options: cleanOptions,
      });
      setModifierForm(emptyModifierForm());
      setShowModifierForm(false);
      fetchModifiers();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al crear el grupo de opciones');
    }
  };

  const deleteModifierGroup = async (id) => {
    if (!window.confirm('¿Eliminar este grupo de opciones? Se quitará de todos los productos que lo usen.')) return;
    try {
      await api.delete(`/modifiers/${id}`);
      fetchModifiers();
      fetchData();
    } catch (err) {
      alert('Error al eliminar el grupo de opciones');
    }
  };

  const handleModifiersChanged = async () => {
    await Promise.all([fetchData(), fetchModifiers()]);
  };

  if (loading) return <p style={{ color: '#94a3b8', textAlign: 'center', padding: 50 }}>Cargando...</p>;

  if (error) return (
    <div>
      <h1 style={{ color: '#e2e8f0', fontSize: 28, marginBottom: 24 }}>🍽️ Gestionar Menú</h1>
      <div className="card" style={{ textAlign: 'center', padding: 40 }}>
        <p style={{ color: '#ef4444', marginBottom: 16 }}>{error}</p>
        <button onClick={fetchData} className="btn btn-primary">Reintentar</button>
      </div>
    </div>
  );

  const filteredProducts = products.filter(p => {
    const matchesCategory = activeCategoryTab === 'all' || p.category_id === activeCategoryTab;
    const matchesSearch = !searchTerm || p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20, flexWrap: 'wrap', gap: 12 }}>
        <h1 style={{ color: '#e2e8f0', fontSize: 28 }}>🍽️ Gestionar Menú</h1>
        <button onClick={() => { resetForm(); setShowForm(!showForm); }} className="btn btn-primary">
          {showForm ? 'Cancelar' : '+ Nuevo Plato'}
        </button>
      </div>

      {/* ===== Categorías (tabs con drag & drop, editar, eliminar) ===== */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 16, flexWrap: 'wrap', alignItems: 'center' }}>
        <button
          onClick={() => setActiveCategoryTab('all')}
          style={{
            padding: '8px 16px', borderRadius: 20, border: 'none',
            background: activeCategoryTab === 'all' ? '#38bdf8' : '#1e293b',
            color: activeCategoryTab === 'all' ? '#0f172a' : '#94a3b8',
            fontWeight: 600, cursor: 'pointer', fontSize: 13,
          }}
        >
          Todas ({products.length})
        </button>

        {categories.map(cat => (
          <div
            key={cat.id}
            draggable
            onDragStart={() => setDraggedCategoryId(cat.id)}
            onDragOver={e => e.preventDefault()}
            onDrop={() => handleCategoryDrop(cat)}
            style={{
              display: 'flex', alignItems: 'center', gap: 6,
              padding: '6px 8px 6px 16px', borderRadius: 20,
              background: activeCategoryTab === cat.id ? '#38bdf8' : '#1e293b',
              cursor: 'grab', opacity: draggedCategoryId === cat.id ? 0.4 : 1,
            }}
          >
            <span
              onClick={() => setActiveCategoryTab(cat.id)}
              style={{
                color: activeCategoryTab === cat.id ? '#0f172a' : '#94a3b8',
                fontWeight: 600, fontSize: 13, cursor: 'pointer',
              }}
            >
              {cat.icon} {cat.name} ({(products.filter(p => p.category_id === cat.id)).length})
            </span>
            <button
              onClick={() => startEditCategory(cat)}
              title="Editar categoría"
              style={{
                background: 'transparent', border: 'none', cursor: 'pointer', fontSize: 12,
                color: activeCategoryTab === cat.id ? '#0f172a' : '#38bdf8',
              }}
            >✏️</button>
            <button
              onClick={() => deleteCategory(cat)}
              title="Eliminar categoría"
              style={{
                background: 'transparent', border: 'none', cursor: 'pointer', fontSize: 12,
                color: activeCategoryTab === cat.id ? '#0f172a' : '#ef4444',
              }}
            >🗑️</button>
          </div>
        ))}

        <button
          onClick={() => { resetCategoryForm(); setShowCategoryForm(!showCategoryForm); }}
          style={{
            padding: '8px 16px', borderRadius: 20, border: '1px dashed #475569',
            background: 'transparent', color: '#94a3b8', fontWeight: 600, cursor: 'pointer', fontSize: 13,
          }}
        >
          + Nueva categoría
        </button>
      </div>

      {showCategoryForm && (
        <div className="card" style={{ marginBottom: 20, maxWidth: 480 }}>
          <h4 style={{ color: '#e2e8f0', marginBottom: 12 }}>
            {editingCategory ? '✏️ Editar categoría' : 'Nueva categoría'}
          </h4>
          <form onSubmit={submitCategoryForm} style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            <div style={{ display: 'flex', gap: 8 }}>
              <input
                type="text"
                placeholder="🍕"
                className="input"
                style={{ width: 60, textAlign: 'center' }}
                value={categoryForm.icon}
                onChange={e => setCategoryForm({ ...categoryForm, icon: e.target.value })}
                maxLength={4}
              />
              <input
                type="text"
                placeholder="Nombre de la categoría *"
                className="input"
                style={{ flex: 1 }}
                value={categoryForm.name}
                onChange={e => setCategoryForm({ ...categoryForm, name: e.target.value })}
                required
              />
            </div>
            <input
              type="text"
              placeholder="Descripción (opcional)"
              className="input"
              value={categoryForm.description}
              onChange={e => setCategoryForm({ ...categoryForm, description: e.target.value })}
            />
            <button type="submit" className="btn btn-success">
              {editingCategory ? '💾 Guardar Cambios' : '+ Crear Categoría'}
            </button>
          </form>
        </div>
      )}

      {/* ===== Buscador ===== */}
      <div style={{ marginBottom: 20, maxWidth: 360 }}>
        <input
          type="text"
          placeholder="🔍 Buscar producto por nombre..."
          className="input"
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
      </div>

      {showForm && (
        <div className="card" style={{ marginBottom: 24 }}>
          <h3 style={{ color: '#e2e8f0', marginBottom: 16 }}>
            {editingProduct ? '✏️ Editar Producto' : 'Crear Producto'}
          </h3>
          <form onSubmit={handleSubmit} style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 12 }}>
            <input type="text" placeholder="Nombre *" className="input" value={form.name} onChange={e => setForm({...form, name: e.target.value})} required />
            <select className="input" value={form.category_id} onChange={e => setForm({...form, category_id: e.target.value})} required>
              <option value="">Categoría *</option>
              {categories.map(c => <option key={c.id} value={c.id}>{c.icon} {c.name}</option>)}
            </select>
            <input type="number" step="0.01" placeholder="Precio *" className="input" value={form.price} onChange={e => setForm({...form, price: e.target.value})} required />
            <input type="number" step="0.01" placeholder="Costo" className="input" value={form.cost} onChange={e => setForm({...form, cost: e.target.value})} />
            <input type="number" placeholder="Tiempo (min)" className="input" value={form.preparation_time_min} onChange={e => setForm({...form, preparation_time_min: e.target.value})} />
            <input type="text" placeholder="URL modelo 3D (AR)" className="input" value={form.model_3d_url} onChange={e => setForm({...form, model_3d_url: e.target.value})} />

            <div style={{ gridColumn: 'span 2' }}>
              <ImageUploadButton value={form.image_url} onChange={url => setForm({ ...form, image_url: url })} label="Foto del plato" />
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <input type="checkbox" id="avail" checked={form.is_available} onChange={e => setForm({...form, is_available: e.target.checked})} style={{ width: 18, height: 18 }} />
              <label htmlFor="avail" style={{ color: '#e2e8f0', fontSize: 14 }}>Disponible</label>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <input type="checkbox" id="isCombo" checked={form.is_combo} onChange={e => setForm({...form, is_combo: e.target.checked})} style={{ width: 18, height: 18 }} />
              <label htmlFor="isCombo" style={{ color: '#e2e8f0', fontSize: 14 }}>🍔 Es un combo/promoción</label>
            </div>

            {form.is_combo && (
              <div style={{ gridColumn: 'span 2', background: '#0f172a', borderRadius: 10, padding: 14 }}>
                <p style={{ color: '#94a3b8', fontSize: 12, marginBottom: 10 }}>
                  Elige qué productos incluye este combo y en qué cantidad:
                </p>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8, maxHeight: 220, overflowY: 'auto' }}>
                  {products.filter(p => !editingProduct || p.id !== editingProduct.id).map(p => (
                    <div key={p.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
                      <label style={{ display: 'flex', alignItems: 'center', gap: 8, flex: 1, cursor: 'pointer' }}>
                        <input
                          type="checkbox"
                          checked={comboItems[p.id] !== undefined}
                          onChange={e => {
                            setComboItems(prev => {
                              const next = { ...prev };
                              if (e.target.checked) next[p.id] = 1; else delete next[p.id];
                              return next;
                            });
                          }}
                        />
                        <span style={{ color: '#e2e8f0', fontSize: 13 }}>{p.name}</span>
                        <span style={{ color: '#64748b', fontSize: 11 }}>${p.price?.toFixed(2)}</span>
                      </label>
                      {comboItems[p.id] !== undefined && (
                        <input
                          type="number"
                          min="1"
                          className="input"
                          style={{ width: 70, padding: '4px 8px' }}
                          value={comboItems[p.id]}
                          onChange={e => setComboItems(prev => ({ ...prev, [p.id]: e.target.value }))}
                        />
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}

            <textarea placeholder="Descripción" className="input" value={form.description} onChange={e => setForm({...form, description: e.target.value})} style={{ gridColumn: 'span 2', minHeight: 60 }} />
            <textarea placeholder="Historia" className="input" value={form.history} onChange={e => setForm({...form, history: e.target.value})} style={{ gridColumn: 'span 2', minHeight: 60 }} />
            <textarea placeholder="Ingredientes" className="input" value={form.ingredients} onChange={e => setForm({...form, ingredients: e.target.value})} style={{ gridColumn: 'span 2', minHeight: 60 }} />
            <button type="submit" className="btn btn-success" style={{ gridColumn: 'span 2' }}>
              {editingProduct ? '💾 Guardar Cambios' : 'Crear Plato'}
            </button>
          </form>
        </div>
      )}

      {activeCategoryTab !== 'all' && (
        <p style={{ color: '#64748b', fontSize: 12, marginBottom: 12 }}>
          🔀 Arrastra las tarjetas para cambiar el orden en que aparecen en el menú.
        </p>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 16, marginBottom: 40 }}>
        {filteredProducts.map(product => (
          <div
            key={product.id}
            className="card"
            draggable={activeCategoryTab !== 'all'}
            onDragStart={() => setDraggedProductId(product.id)}
            onDragOver={e => e.preventDefault()}
            onDrop={() => handleProductDrop(product)}
            style={{
              cursor: activeCategoryTab !== 'all' ? 'grab' : 'default',
              opacity: draggedProductId === product.id ? 0.4 : 1,
            }}
          >
            <div style={{ width: '100%', height: 140, borderRadius: 10, background: product.image_url ? `url(${product.image_url}) center/cover` : '#334155', marginBottom: 12, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 40, position: 'relative' }}>
              {!product.image_url && '🍽️'}
              {product.is_combo && (
                <span style={{ position: 'absolute', top: 8, left: 8, background: '#a855f7', color: '#fff', fontSize: 10, fontWeight: 700, padding: '3px 8px', borderRadius: 6 }}>
                  🍔 COMBO
                </span>
              )}
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
              <h4 style={{ color: '#e2e8f0', fontSize: 15 }}>{product.name}</h4>
              <span style={{ color: '#fbbf24', fontWeight: 700 }}>${product.price?.toFixed(2)}</span>
            </div>
            <p style={{ color: '#94a3b8', fontSize: 12, marginBottom: 6 }}>{product.categoryName}</p>
            {product.modifiers?.length > 0 && (
              <p style={{ color: '#a855f7', fontSize: 11, marginBottom: 10 }}>
                ⚙️ {product.modifiers.map(m => m.name).join(' · ')}
              </p>
            )}
            <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
              <button onClick={() => toggleAvailability(product.id, product.is_available)} style={{ padding: '5px 10px', borderRadius: 6, border: 'none', background: product.is_available ? 'rgba(16,185,129,0.1)' : 'rgba(239,68,68,0.1)', color: product.is_available ? '#10b981' : '#ef4444', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>
                {product.is_available ? '✓ Disponible' : '✗ No disponible'}
              </button>
              <button onClick={() => setAssignModalProduct(product)} style={{ padding: '5px 10px', borderRadius: 6, border: 'none', background: 'rgba(168,85,247,0.1)', color: '#a855f7', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>⚙️ Opciones</button>
              <button onClick={() => duplicateProduct(product.id)} style={{ padding: '5px 10px', borderRadius: 6, border: 'none', background: 'rgba(148,163,184,0.15)', color: '#cbd5e1', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>📋 Duplicar</button>
              <button onClick={() => startEdit(product)} style={{ padding: '5px 10px', borderRadius: 6, border: 'none', background: 'rgba(56,189,248,0.1)', color: '#38bdf8', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>✏️ Editar</button>
              <button onClick={() => deleteProduct(product.id)} style={{ padding: '5px 10px', borderRadius: 6, border: 'none', background: 'rgba(239,68,68,0.1)', color: '#ef4444', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>🗑️ Eliminar</button>
            </div>
          </div>
        ))}
        {filteredProducts.length === 0 && (
          <p style={{ color: '#64748b', gridColumn: '1 / -1', textAlign: 'center', padding: 30 }}>
            No hay productos que coincidan con la búsqueda/categoría.
          </p>
        )}
      </div>

      {/* ===== Opciones / Modificadores ===== */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <div>
          <h2 style={{ color: '#e2e8f0', fontSize: 22 }}>⚙️ Opciones / Modificadores</h2>
          <p style={{ color: '#64748b', fontSize: 13, marginTop: 4 }}>
            Crea grupos de opciones (ej: "Término de cocción", "Con/Sin papas", "Tipo de bebida") con "✏️ Editar" agregas, editas o quitas opciones sueltas. Luego, en cada plato usa "⚙️ Opciones" para activar el grupo y elegir cuáles de sus opciones aplican a ese plato en particular.
          </p>
        </div>
        <button onClick={() => { setModifierForm(emptyModifierForm()); setShowModifierForm(!showModifierForm); }} className="btn btn-primary">
          {showModifierForm ? 'Cancelar' : '+ Nuevo grupo de opciones'}
        </button>
      </div>

      {showModifierForm && (
        <div className="card" style={{ marginBottom: 24 }}>
          <form onSubmit={submitModifierForm}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 12, marginBottom: 16 }}>
              <input type="text" placeholder="Nombre del grupo * (ej: Tipo de bebida)" className="input" value={modifierForm.name} onChange={e => setModifierForm({...modifierForm, name: e.target.value})} required />
              <input type="text" placeholder="Descripción (opcional)" className="input" value={modifierForm.description} onChange={e => setModifierForm({...modifierForm, description: e.target.value})} />
              <div>
                <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>Selecciones mínimas (0 = opcional)</label>
                <input type="number" min="0" className="input" value={modifierForm.min_selections} onChange={e => setModifierForm({...modifierForm, min_selections: e.target.value})} />
              </div>
              <div>
                <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>Selecciones máximas (1 = elegir solo una)</label>
                <input type="number" min="1" className="input" value={modifierForm.max_selections} onChange={e => setModifierForm({...modifierForm, max_selections: e.target.value})} />
              </div>
            </div>

            <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 8 }}>
              Opciones iniciales (después puedes agregar, editar o quitar más con "✏️ Editar")
            </label>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 12 }}>
              {modifierForm.options.map((opt, i) => (
                <div key={i} style={{ display: 'flex', gap: 8 }}>
                  <input
                    type="text"
                    placeholder="Nombre de la opción"
                    className="input"
                    style={{ flex: 1 }}
                    value={opt.name}
                    onChange={e => updateModifierOption(i, 'name', e.target.value)}
                  />
                  <input
                    type="number"
                    step="0.01"
                    placeholder="+/- precio"
                    className="input"
                    style={{ width: 120 }}
                    value={opt.price_adjustment}
                    onChange={e => updateModifierOption(i, 'price_adjustment', e.target.value)}
                  />
                  <button type="button" onClick={() => removeModifierOptionRow(i)} style={{ background: 'rgba(239,68,68,0.1)', color: '#ef4444', border: 'none', borderRadius: 8, width: 40, cursor: 'pointer' }}>✕</button>
                </div>
              ))}
            </div>
            <button type="button" onClick={addModifierOptionRow} className="btn" style={{ background: '#334155', color: '#e2e8f0', marginBottom: 16 }}>
              + Agregar opción
            </button>

            <button type="submit" className="btn btn-success" style={{ width: '100%' }}>
              💾 Guardar grupo de opciones
            </button>
          </form>
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 16 }}>
        {modifiers.map(mod => (
          <div key={mod.id} className="card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 8 }}>
              <h4 style={{ color: '#e2e8f0', fontSize: 15 }}>{mod.name}</h4>
              <div style={{ display: 'flex', gap: 6 }}>
                <button onClick={() => setEditModifierTarget(mod)} style={{ background: 'rgba(56,189,248,0.1)', color: '#38bdf8', border: 'none', borderRadius: 6, padding: '4px 8px', fontSize: 11, cursor: 'pointer' }}>✏️</button>
                <button onClick={() => deleteModifierGroup(mod.id)} style={{ background: 'rgba(239,68,68,0.1)', color: '#ef4444', border: 'none', borderRadius: 6, padding: '4px 8px', fontSize: 11, cursor: 'pointer' }}>🗑️</button>
              </div>
            </div>
            {mod.description && <p style={{ color: '#64748b', fontSize: 12, marginBottom: 8 }}>{mod.description}</p>}
            <p style={{ color: '#94a3b8', fontSize: 11, marginBottom: 10 }}>
              Mín {mod.min_selections} · Máx {mod.max_selections}
            </p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
              {mod.options?.map(opt => (
                <div key={opt.id} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12 }}>
                  <span style={{ color: '#cbd5e1' }}>{opt.name}</span>
                  <span style={{ color: parseFloat(opt.price_adjustment) > 0 ? '#fbbf24' : '#64748b' }}>
                    {parseFloat(opt.price_adjustment) > 0 ? `+$${parseFloat(opt.price_adjustment).toFixed(2)}` : 'Incluido'}
                  </span>
                </div>
              ))}
              {(!mod.options || mod.options.length === 0) && (
                <p style={{ color: '#64748b', fontSize: 12 }}>Sin opciones — edítalo para agregar.</p>
              )}
            </div>
          </div>
        ))}
        {modifiers.length === 0 && (
          <p style={{ color: '#64748b', gridColumn: '1 / -1', textAlign: 'center', padding: 30 }}>
            Todavía no creaste ningún grupo de opciones.
          </p>
        )}
      </div>

      {assignModalProduct && (
        <AssignModifiersModal
          product={assignModalProduct}
          allModifiers={modifiers}
          onClose={() => setAssignModalProduct(null)}
          onChanged={handleModifiersChanged}
        />
      )}

      {editModifierTarget && (
        <EditModifierModal
          modifier={editModifierTarget}
          onClose={() => setEditModifierTarget(null)}
          onSaved={fetchModifiers}
        />
      )}
    </div>
  );
};

export default MenuPage;
